begin transaction isolation level repeatable read read only;
with names as(select jsonb_array_elements_text('["젤로 0.8 팟","아보카도베이비프로 0.6 팟","디오X 0.6 팟","팬텀 엔트리 케이스","빔버니리유즈 배터리","발라리안맥스프로 투명케이스 신형","발라리안 0.6 코일","젤로맥스 투명케이스","젤로맥스 0.6 팟","젤로 1.2 팟","말론 투명케이스","글렌트/글렌트프로 투명케이스","하부코일 1.6","젤로 투명케이스","발라리안맥스프로 0.5 팟","말론S 0.6 팟","말론S 투명케이스","젤로맥스 0.6 팟 (5ml)","디오X 투명케이스","젤로 0.8 부스트팟","아보카도 aio 0.6 팟","하복 공팟 클리어","하복 0.6 코일","말론 0.6 팟"]'::jsonb) item),
m as(select item_name,reference_type,reference_id,sum(quantity_delta) qty,min(created_at) at,jsonb_agg(jsonb_build_object('type',movement_type,'q',quantity_delta,'after',quantity_after,'at',created_at,'note',note) order by created_at,id) details from inventory_movements where item_name in(select item from names) group by 1,2,3),
e as(select item_name,case when reference_type='stamp_log' then 'outbound_log' else reference_type end ref,reference_id,sum(case when direction='in' then quantity else -quantity end) qty,min(event_at) at,jsonb_agg(jsonb_build_object('type',event_type,'q',quantity,'at',event_at,'cost',total_cost,'meta',metadata)) details from inventory_cost_events where item_name in(select item from names) and event_at>='2026-07-22 00:00:00+09' and metadata->>'restoredAt' is null group by 1,2,3)
select coalesce(m.item_name,e.item_name) item,coalesce(m.reference_type,e.ref) ref,coalesce(m.reference_id,e.reference_id) id, m.qty stock_delta,e.qty cost_delta,coalesce(e.qty,0)-coalesce(m.qty,0) difference,m.details movements,e.details events from m full join e on m.item_name=e.item_name and m.reference_type=e.ref and m.reference_id=e.reference_id where coalesce(m.qty,0)<>coalesce(e.qty,0) order by 1,2,3;
commit;
